[[vk::binding(0, 0)]] RWTexture2D<float4> gOutput;
[[vk::binding(1, 0)]] cbuffer Host {
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};
[[vk::binding(2, 0)]] RaytracingAccelerationStructure gScene;

struct Payload { float4 c; };

[shader("raygeneration")]
void RayGen()
{
    uint2 idx = DispatchRaysIndex().xy;
    uint2 dim = DispatchRaysDimensions().xy;
    float2 uv = (float2(idx) + 0.5) / float2(dim);
    float2 ndc = uv * 2.0 - 1.0;
    ndc.y = -ndc.y;
    float aspect = float(dim.x) / float(dim.y);
    float3 dir = normalize(float3(ndc.x * aspect, ndc.y, 2.0));

    RayDesc ray;
    ray.Origin = float3(0, 0.5, -3);
    ray.TMin = 0.001;
    ray.Direction = dir;
    ray.TMax = 100.0;

    Payload p;
    p.c = float4(0, 0, 0, 1);
    TraceRay(gScene, RAY_FLAG_NONE, 0xFF, 0, 0, 0, ray, p);
    gOutput[idx] = p.c;
}

struct Payload { float4 c; };
[shader("miss")]
void Miss(inout Payload p)
{
    p.c = float4(0.05, 0.05, 0.15, 1.0);
}

struct Payload { float4 c; };
struct MaterialData { float3 color; float roughness; };

[shader("closesthit")]
void ClosestHit(inout Payload p, in BuiltInTriangleIntersectionAttributes a)
{
    uint matIndex = PrimitiveIndex() % 3;
    MaterialData mat;
    mat.color = float3(0.5, 0.5, 0.5);
    mat.roughness = 0.5;
    CallShader(matIndex, mat);
    float3 normal = normalize(float3(0, 1, 0));
    float3 lightDir = normalize(float3(0.5, 1, -0.3));
    float diff = max(dot(normal, lightDir), 0.0);
    float3 col = mat.color * (0.2 + 0.8 * diff);
    p.c = float4(col, 1.0);
}

struct MaterialData { float3 color; float roughness; };

[shader("callable")]
void MatRed(inout MaterialData mat)
{
    mat.color = float3(0.9, 0.2, 0.1);
    mat.roughness = 0.3;
}

struct MaterialData { float3 color; float roughness; };

[shader("callable")]
void MatGreen(inout MaterialData mat)
{
    mat.color = float3(0.1, 0.8, 0.2);
    mat.roughness = 0.7;
}

struct MaterialData { float3 color; float roughness; };

[shader("callable")]
void MatBlue(inout MaterialData mat)
{
    mat.color = float3(0.1, 0.3, 0.9);
    mat.roughness = 0.1;
}
